{
  "name": "@yaoguai_xh/opencode-goal-plugin",
  "version": "0.10.3",
  "description": "Durable, guarded goal workflows for OpenCode.",
  "type": "module",
  "main": "./src/goal-plugin.js",
  "types": "./index.d.ts",
  "exports": {
    ".": {
      "types": "./index.d.ts",
      "import": "./src/goal-plugin.js",
      "default": "./src/goal-plugin.js"
    },
    "./server": {
      "types": "./index.d.ts",
      "import": "./src/goal-plugin.js",
      "default": "./src/goal-plugin.js"
    },
    "./tui": {
      "import": "./src/tui.js",
      "default": "./src/tui.js"
    }
  },
  "bin": {
    "opencode-goal-plugin": "./scripts/verify.mjs"
  },
  "files": [
    "src",
    "scripts/verify.mjs",
    "examples",
    "demo",
    "docs",
    "index.d.ts",
    "README.md",
    "CHANGELOG.md",
    "CONTRIBUTING.md",
    "SECURITY.md",
    "LICENSE",
    ".nvmrc"
  ],
  "scripts": {
    "test": "node --test test/*.test.js",
    "test:model": "node --test test/lifecycle-model.test.js",
    "test:mutation": "node scripts/mutation-contract.mjs",
    "test:coverage": "node --test --experimental-test-coverage test/*.test.js",
    "type:check": "node scripts/type-contract.mjs",
    "smoke": "node scripts/smoke-command-hook.mjs",
    "smoke:packed-host": "node scripts/packed-host-contract.mjs",
    "smoke:packed-tools": "node scripts/packed-tool-contract.mjs",
    "benchmark:behavior": "node scripts/behavior-benchmark.mjs",
    "verify": "node scripts/verify.mjs",
    "check": "node -c src/goal-plugin.js && npm test",
    "pack:check": "npm pack --dry-run",
    "release:check": "npm run check && npm run test:coverage && npm run type:check && npm run test:mutation && npm run benchmark:behavior && npm run smoke && npm run smoke:packed-host && npm run smoke:packed-tools && npm run verify && npm audit --omit=dev --audit-level=high && npm run pack:check"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "agent",
    "goal"
  ],
  "license": "MIT",
  "engines": {
    "node": ">=18",
    "opencode": ">=1.17.15 <2"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/yaoguai-xh/OpenCode-goal-plugin.git"
  },
  "bugs": {
    "url": "https://github.com/yaoguai-xh/OpenCode-goal-plugin/issues"
  },
  "homepage": "https://github.com/yaoguai-xh/OpenCode-goal-plugin#readme",
  "author": {
    "name": "willytop8"
  },
  "contributors": [
    {
      "name": "yaoguai-xh",
      "url": "https://github.com/yaoguai-xh/OpenCode-goal-plugin"
    }
  ],
  "devDependencies": {
    "typescript": "7.0.2"
  },
  "dependencies": {
    "zod": "4.5.4"
  },
  "peerDependencies": {
    "@opentui/solid": ">=0.5.8",
    "solid-js": ">=1.9.0"
  }
}

{
  "$schema": "https://opencode.ai/config.json",
  "plugin": ["file:../src/goal-plugin.js"],
  "command": {
    "goal": {
      "description": "Set a session-scoped goal and auto-continue until complete.",
      "template": "$ARGUMENTS",
      "agent": "build"
    }
  }
}

{
  "name": "opencode-goal-plugin-demo",
  "private": true,
  "version": "1.0.0",
  "description": "Minimal reproducible demo: a failing test and a /goal that fixes it autonomously.",
  "type": "module",
  "scripts": {
    "test": "node --test"
  }
}

{
  "$schema": "https://opencode.ai/config.json",
  "plugin": ["@yaoguai_xh/opencode-goal-plugin@latest"],
  "command": {
    "goal": {
      "description": "Set a session-scoped goal and auto-continue until complete.",
      "template": "$ARGUMENTS",
      "agent": "build"
    }
  }
}
